'use strict';

function validateCatalog(catalog) {
  if (!Array.isArray(catalog)) throw new TypeError('catalog must be an array');
  const labels = new Set();
  for (const entry of catalog) {
    if (!entry || typeof entry !== 'object' || typeof entry.label !== 'string' ||
        entry.label.trim().length === 0 || !Number.isSafeInteger(entry.createdIndex) ||
        entry.createdIndex < 0 || typeof entry.purpose !== 'string') {
      throw new TypeError('invalid catalog entry');
    }
    if (labels.has(entry.label)) throw new RangeError('duplicate catalog label');
    labels.add(entry.label);
  }
}

function registerTopic(catalog, label, createdIndex) {
  validateCatalog(catalog);
  if (typeof label !== 'string' || label.trim().length === 0) {
    throw new TypeError('label must be non-empty');
  }
  if (!Number.isSafeInteger(createdIndex) || createdIndex < 0) {
    throw new TypeError('createdIndex must be a non-negative safe integer');
  }
  const normalized = label.trim();
  if (catalog.some(entry => entry.label === normalized)) {
    throw new RangeError('duplicate catalog label');
  }
  const result = catalog.map(entry => ({ ...entry }));
  result.unshift({ label: normalized, createdIndex, purpose: 'discussion' });
  return result;
}

function leaveTopic(session) {
  if (!session || typeof session !== 'object' ||
      !Object.prototype.hasOwnProperty.call(session, 'member') ||
      !Object.prototype.hasOwnProperty.call(session, 'topic')) {
    throw new TypeError('invalid session');
  }
  return { ...session, member: null, topic: null };
}

module.exports = { registerTopic, leaveTopic };

