'use strict';

const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['registerTopic', 'leaveTopic']);
const { registerTopic, leaveTopic } = api;

const catalog = [
  { label: 'General', createdIndex: 0, purpose: 'discussion' },
  { label: 'Engineering', createdIndex: 4, purpose: 'discussion' }
];
const before = catalog.map(entry => ({ ...entry }));
const registered = registerTopic(catalog, '  Support  ', Number.MAX_SAFE_INTEGER);
assert.deepStrictEqual(registered, [
  ...before,
  { label: 'Support', createdIndex: Number.MAX_SAFE_INTEGER, purpose: 'discussion' }
]);
assert.notStrictEqual(registered, catalog);
assert.notStrictEqual(registered[0], catalog[0]);
assert.notStrictEqual(registered[1], catalog[1]);
assert.deepStrictEqual(catalog, before);
registered[0].label = 'changed';
registered[2].label = 'changed-new';
assert.strictEqual(catalog[0].label, 'General');
assert.deepStrictEqual(registerTopic([], 'First', 0), [
  { label: 'First', createdIndex: 0, purpose: 'discussion' }
]);
assert.throws(() => registerTopic(catalog, ' General ', 9), RangeError);
for (const label of ['', '   ', null, 1]) {
  assert.throws(() => registerTopic([], label, 0), TypeError);
}
for (const index of [-1, 1.5, Number.MAX_SAFE_INTEGER + 1, '0']) {
  assert.throws(() => registerTopic([], 'x', index), TypeError);
}
for (const badCatalog of [null, {}, [null], [{ label: '', createdIndex: 0, purpose: 'discussion' }], [{ label: 'x', createdIndex: -1, purpose: 'discussion' }], [{ label: 'x', createdIndex: 0, purpose: 1 }]]) {
  assert.throws(() => registerTopic(badCatalog, 'new', 1), TypeError);
}
assert.throws(() => registerTopic([
  { label: 'x', createdIndex: 0, purpose: 'discussion' },
  { label: 'x', createdIndex: 1, purpose: 'discussion' }
], 'new', 2));

const session = { member: { id: 1 }, topic: 'General', token: 'abc', count: 2 };
const sessionBefore = { ...session };
const left = leaveTopic(session);
assert.deepStrictEqual(left, { member: null, topic: null, token: 'abc', count: 2 });
assert.notStrictEqual(left, session);
assert.deepStrictEqual(session, sessionBefore);

const prototypeOnly = Object.create({ member: 'm', topic: 't' });
assert.throws(() => leaveTopic(prototypeOnly), TypeError);
for (const bad of [null, 1, 'session', {}, { member: 'm' }, { topic: 't' }]) {
  assert.throws(() => leaveTopic(bad), TypeError);
}

